import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, calculateDueDate } from './dates.js';
import { lineTotal, lineDiscount, lineVat, invoiceTotals } from './totals.js';

export { lineTotal, lineDiscount, lineVat, invoiceTotals };

/**
 * Validate that a discount is a number from 0 to 100.
 * @param {unknown} discount
 * @returns {boolean}
 */
function isValidDiscount(discount) {
  return typeof discount === 'number' && !isNaN(discount) && discount >= 0 && discount <= 100;
}

/**
 * Add or increase a line on a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string, qty: number, unitPrice: number, vatRate: number, name: string }>, customerId: string, issueDate: string }} invoice
 * @param {{ sku: string, qty: number }} item
 * @returns {import('./result.js').Result<{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }>}
 */
export function addLine(invoice, item) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(item.qty) || item.qty <= 0) return fail('QTY_INVALID');

  if (item.discountPercent !== undefined && !isValidDiscount(item.discountPercent)) return fail('DISCOUNT_INVALID');

  const productResult = getProduct(item.sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === item.sku);

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex].qty += item.qty;
  } else {
    newLines.push({
      sku: item.sku,
      name: product.name,
      qty: item.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: item.discountPercent ?? 0,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string }>, customerId: string, issueDate: string }} invoice
 * @param {string} sku
 * @returns {import('./result.js').Result<{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }>}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku).map((line) => ({ ...line }));

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ status: string, voucher?: { code: string, amount: number } }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {import('./result.js').Result<{ voucher: { code: string, amount: number } }>}
 */
export function applyVoucher(invoice, voucher) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  if (!Number.isInteger(voucher.amount) || voucher.amount <= 0) return fail('AMOUNT_INVALID');

  return ok({
    ...invoice,
    voucher: {
      code: voucher.code,
      amount: voucher.amount,
    },
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }>, terms?: string, dueDate?: string, voucher?: { code: string, amount: number } }} invoice
 * @param {Array<string>} existingNumbers - Invoice numbers already issued
 * @returns {import('./result.js').Result<{ number: string, customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }>, terms?: string, dueDate?: string, voucher?: { code: string, amount: number } }>}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    number,
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
    ...(invoice.terms && { terms: invoice.terms }),
    ...(invoice.dueDate && { dueDate: invoice.dueDate }),
    ...(invoice.voucher && { voucher: { ...invoice.voucher } }),
  });
}

/**
 * Create a new draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} invoice
 * @returns {import('./result.js').Result<{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }>, terms: string, dueDate: string }>}
 */
export function createInvoice(invoice) {
  const { customerId, issueDate, lines, terms: inputTerms } = invoice;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  const terms = inputTerms ?? 'NET30';
  const validTerms = ['NET14', 'NET30', 'EOM'];
  if (!validTerms.includes(terms)) return fail('TERMS_INVALID');

  const dueDate = calculateDueDate(issueDate, terms);
  if (!dueDate) return fail('TERMS_INVALID');

  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  if (!lines || lines.length === 0) return fail('NO_LINES');

  const enrichedLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    if (line.discountPercent !== undefined && !isValidDiscount(line.discountPercent)) return fail('DISCOUNT_INVALID');

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const effectiveDiscount = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: effectiveDiscount,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
    terms,
    dueDate,
  });
}

