  assert.equal(typeof vat, 'number');
  assert.equal(vat > 0, true);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 50, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5000);
  const expectedBulkDiscount = 5000 * 0.025;
  assert.equal(totals.discount, expectedBulkDiscount);
  assert.equal(typeof totals.vat, 'number');
  assert.equal(totals.voucher, 0);
  assert.equal(typeof totals.total, 'number');
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 50, vatRate: 21 },
      { qty: 50, unitPrice: 100, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 10000);
});

test('invoiceTotals with discount', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 50, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5000);
  const primaryDiscount = 5000 * 0.1;
  const bulkDiscount = (5000 - primaryDiscount) * 0.025;
  const expectedDiscount = primaryDiscount + bulkDiscount;
  assert.equal(totals.discount, expectedDiscount);
});

test('invoiceTotals with voucher', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 50, vatRate: 21 }],
    voucher: { code: 'SAVE10', amount: 1000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 1000);
  assert.equal(totals.total < totals.subtotal + totals.vat, true);
});

test('invoiceTotals total formula', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 50, discountPercent: 5, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  const expected = totals.subtotal - totals.discount + totals.vat - totals.voucher;
  assert.equal(totals.total, expected);
});

test('invoiceTotals clamps total to 0', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 10, vatRate: 21 }],
    voucher: { code: 'BIG', amount: 100000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with empty lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals includes all required fields', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 50, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(Object.keys(totals).length, 5);
  assert.equal('subtotal' in totals, true);
  assert.equal('discount' in totals, true);
  assert.equal('vat' in totals, true);
  assert.equal('voucher' in totals, true);
  assert.equal('total' in totals, true);
});

test('lineBulkDiscount is 0 for qty < 10', () => {
  const line = { qty: 9, unitPrice: 100 };
  assert.equal(lineBulkDiscount(line), 0);
});

test('lineBulkDiscount is 0 for qty exactly 9', () => {
  const line = { qty: 9, unitPrice: 100 };
  assert.equal(lineBulkDiscount(line), 0);
});

test('lineBulkDiscount applies 2.5% for qty >= 10', () => {
  const line = { qty: 10, unitPrice: 100 };
  const bulkDiscount = lineBulkDiscount(line);
  assert.equal(bulkDiscount > 0, true);
  const expected = 1000 * 0.025;
  assert.equal(bulkDiscount, expected);
});

test('lineBulkDiscount applies after primary discount', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 10 };
  const bulkDiscount = lineBulkDiscount(line);
  const primaryDiscount = lineDiscount(line);
  const amountAfterPrimary = lineTotal(line) - primaryDiscount;
  const expected = amountAfterPrimary * 0.025;
  assert.equal(bulkDiscount, expected);
});

test('lineBulkDiscount with large qty', () => {
  const line = { qty: 1000, unitPrice: 50 };
  const bulkDiscount = lineBulkDiscount(line);
  const expected = 50000 * 0.025;
  assert.equal(bulkDiscount, expected);
});

test('lineVat uses amount after bulk discount', () => {
  const line = { qty: 10, unitPrice: 100, vatRate: 21 };
  const vat = lineVat(line);
  const lineTotal_ = lineTotal(line);
  const bulkDiscount = lineBulkDiscount(line);
  const amountAfterDiscount = lineTotal_ - bulkDiscount;
  const expected = roundCents(amountAfterDiscount * 0.21);
  assert.equal(vat, expected);
});

test('invoiceTotals includes bulk discount in discount field', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 100, discountPercent: 5, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  const primaryDiscount = 1000 * 0.05;
  const bulkDiscount = (1000 - primaryDiscount) * 0.025;
  const expectedDiscount = primaryDiscount + bulkDiscount;
  assert.equal(totals.discount, expectedDiscount);
});

test('invoiceTotals with mixed qty (bulk and non-bulk lines)', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 100, vatRate: 21 },
      { qty: 10, unitPrice: 100, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1Discount = 0;
  const line2Discount = 0;
  const line1BulkDiscount = 0;
  const line2BulkDiscount = 1000 * 0.025;
  const expectedDiscount = line1Discount + line2Discount + line1BulkDiscount + line2BulkDiscount;
  assert.equal(totals.discount, expectedDiscount);
});

test('invoiceTotals total formula with bulk discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 100, discountPercent: 5, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  const expected = totals.subtotal - totals.discount + totals.vat - totals.voucher;
  assert.equal(totals.total, expected);
});

test('lineBulkDiscount with primary discount 50%', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 50 };
  const bulkDiscount = lineBulkDiscount(line);
  const primaryDiscount = lineDiscount(line);
  const amountAfterPrimary = 1000 - primaryDiscount;
  const expected = amountAfterPrimary * 0.025;
  assert.equal(bulkDiscount, expected);
});

test('bulk discount reduces VAT base', () => {
  const line1 = { qty: 9, unitPrice: 100, vatRate: 21 };
  const line2 = { qty: 10, unitPrice: 100, vatRate: 21 };
  const vat1 = lineVat(line1);
  const vat2 = lineVat(line2);
